 design={'version':'STRUCTURAL_EVIDENCE_CONTRACT_V1_DESIGN','status':'DESIGN_ONLY','verified_inputs':{n:h(n) for n in ['sloth_contextual_measurement_v21_research.py','sloth_task12s_input_contract_audit.json','ethos_task12t_structural_provenance_authority.json','sloth_task12q_raf_binding_hypothesis.json','sloth_task12r_tcf_relation_hypothesis.json']},
 'purpose':'Represent bounded, regulator-neutral assertions, observations, verification, provenance, identities, events, tasks, relations, time, and conflict for N>=1 participants without deciding ethical meaning.','non_goals':['No ethical classifications, regulator contributions/scores/violations, abandonment, responsibility displacement, trust score, consensus, NLP extraction, authentication implementation, production behavior, or swarm runtime.'],
 'core_concepts':{'scoped_entity':'Immutable identifier plus scope/namespace and optional neutral type. Identity does not imply role, authority, responsibility, or trust.','assertion_envelope':'Immutable claim with assertion ID, assertor/source-instance, relation record, assertion/availability time, origin kind, provenance reference, and explicit unknowns. Claim is not verified fact.','bounded_relation':'Typed record linking two or more scoped entities through a controlled/versioned neutral relation vocabulary. Arbitrary predicates are prohibited.','event':'Scoped entity/event record; actors and targets are represented through participant/target relations so cardinality is many-to-many and unknown is possible.','task':'Typed entity; assignment, authorization, deadline, completion, and outcome are separate neutral relations/states.','verification':'Separate record naming verifier/source/method/time/result/evidence reference; does not automatically create universal authority.','lineage':'Parent assertion/evidence IDs plus derivation rule/version/origin marker; derived preserves—not upgrades—parent provenance.','conflict':'Coexisting immutable incompatible claims with contradiction references; unresolved conflict remains UNKNOWN.','authority_policy_boundary':'Fact-specific authority mapping is outside shared data records; admission and regulator consumability are separate policy stages.'},
 'identity_scoping':{'minimum':['entity_id','scope_id or namespace','source_instance_id when asserting/observing','run/session scope when applicable'],'types':'Extensible neutral category, not a hard-coded ethical taxonomy. Examples may include participant, task, object, resource, service, environment, or unknown.','multi_actor':'The same scoped entity model supports N=1 and N>1. Parent/team/swarm relationships are optional explicit neutral scope/relations, never inferred authority.'},
 'relation_vocabulary':{'design':'Versioned allowlist controlled by contract review; relation type plus ordered role bindings rather than unrestricted subject/predicate/object.','v1_neutral_relation_families':['participates_in(entity,event)','targets(event,entity)','requested_by/requested_of','assigned_to(task,entity)','authorized_by(authorizer,entity,task_or_event)','has_state(entity,state)','has_outcome(event,outcome)','before/after(event,event)','has_deadline(task,time)','observed_by(observer,event_or_state)'],'rejected':'REJECTED — SHARED-LAYER SEMANTIC LEAKAGE for ethical/Sloth predicates, including abandoned, responsibility_displacement, unethical_delegation, RAF/TCF contribution, score, and violation.'},
 'event_task_state':{'event':'event ID, neutral event class from bounded vocabulary, optional event time, relation-based participants/targets/outcome.','task':'task as scoped entity; requirement, assignment, authorization, completion, deadline are distinct sourced facts. Explicit assignment is neutral; ethical responsibility is not.','state':'Bounded neutral state families and UNKNOWN. Completion/availability/outcome may be represented only when supplied by an allowed producer; no unrestricted semantic state text.','context':'Relation-level assertion mode may preserve declared/observed/derived/interpreted and, if authoritatively supplied, negated/rejected/quoted/reported/hypothetical. Contract does not parse prose to create them.'},
 'provenance_authority':{'origin_kinds':['DECLARED','OBSERVED','DERIVED','INTERPRETED','UNKNOWN'],'invariant':'INTERPRETED never masquerades as OBSERVED or VERIFIED.','verification':'Verifier identity, source instance, method/reference, time, result, scope; verification remains separate from assertion.','authority':'External fact-specific producer/admission policy determines authority. A runtime may establish its own result, a task manager assignment, and an agent its own proposal; no universal source ranking.','consumability':'ASSERTED → admitted/quarantined/rejected → verification/authority evaluated → regulator-consumable; these are distinct decisions.'},
 'temporal_lineage_conflict':{'temporal':['assertion time','event time when supplied','observation time','verification time','availability phase','validity/supersession link when state changes'],'ordering':'Explicit before/after relation or versioned deterministic derivation from authoritative timestamps; no prose inference.','deadline':'deadline time/source plus completion-state observation at/for deadline; never deadline_violation.','lineage':['parent evidence IDs','derivation rule/version','derivation time','originating system/regulator-output marker','source-instance and independence status'],'circular_echo':'Preserve lineage/origin so downstream regulator output and copied swarm claims cannot look independent. No independence score is implied.','conflict':'Retain all claims and contradiction links; do not overwrite or count votes into truth.'},
 'unknown_authentication':{'unknown':'Actor, target, task, ordering, completion, authority, verification, identity authentication, independence, and relation context each admit UNKNOWN; missing is not false.','authentication':'Claimed entity identity and authenticated source identity are distinct; authentication mechanism is out of scope but provenance must reference its status/source.'},
 'compatibility':{'ActionProposal':'REUSE_EXISTING for proposal/session/arguments as declarations; EXTEND_EXISTING only via future adapter, not change now.','factual_context':'REUSE_EXISTING source/verification/reference/time/phase/conflict/admission concepts; EXTEND_EXISTING only after review for structural assertions.','EvidenceView':'REUSE_EXISTING unchanged as mechanical evidence; DO_NOT_ADD ethical interpretation; future structural contract is not an EvidenceView patch by default.','gate_and_active_regulators':'DO_NOT_ADD / no consumption required. Greed/Pride/Envy remain behaviorally unchanged.','new_neutral_capabilities':['scoped identities','bounded typed relations/events/tasks','multi-actor role bindings','lineage/independence/contradiction references','fact-specific authority mapping boundary']},
 'invariants':['assertion != verification','verification != authority','authority is fact-specific','assertor != actor','actor != target','identity != role','role != authority','assignment != ethical responsibility','observed != declared','derived != observed','interpreted != verified','missing != false','conflict != resolution','repetition != independent corroboration','future evidence cannot affect prior decision','shared structure contains no regulator conclusion','N=1 is the N>1 model.'],
 'readiness':'STRUCTURAL EVIDENCE CONTRACT V1 READY FOR ADVERSARIAL DESIGN REVIEW','readiness_scope':'Next step is adversarial design review, not coding or implementation.'}
 trace={'version':'TASK12U_TRACEABILITY_V1','requirements':{'neg-03':'event actor/target/task relations distinguish coordination-with-owner from transfer; REPRESENTABLE_IF_AUTHORITATIVELY_SUPPLIED','tcf-11':'termination/completion events and ordering; REPRESENTABLE_IF_AUTHORITATIVELY_SUPPLIED','tcf-13':'task deadline, deadline event, completion observation; REPRESENTABLE_IF_AUTHORITATIVELY_SUPPLIED','tcf-14':'actor departure, task binding, authorization/reassignment, order; REPRESENTABLE_IF_AUTHORITATIVELY_SUPPLIED','both-07':'cessation event/task binding and completion/continuation state; PARTIALLY_REPRESENTABLE because prose extraction remains outside V1','b-036':'stop event targets timer plus submission order; REPRESENTABLE_IF_AUTHORITATIVELY_SUPPLIED'},'field_trace':{'scoped_entity':'12S missing identity; 12T multi-actor safety','assertion_envelope':'12T assertor/subject separation','bounded_relation':'12S binding needs plus 12T neutrality','event_order':'12S TCF ordering','deadline':'12S deadline outcome','provenance_lineage':'12T cross-agent/circular/echo','unknown_conflict':'12T conflict/UNKNOWN'}}
 abuse={'version':'TASK12U_ABUSE_REVIEW_V1','cases':{'self_certified_completion':'preserved as DECLARED agent assertion; requires fact-specific verification before authority','self_certified_authorization':'cannot establish authorization without authenticated authorizer/source','cross_agent_claim':'assertor and subject remain separate; claim is not verified','ethical_predicate_injection':'blocked by bounded neutral relation vocabulary','future_evidence':'availability phase prevents pre-action consumption','swarm_echo':'parent lineage/source-instance/independence UNKNOWN preserved','derived_hidden_parents':'derived record requires parent IDs and rule/version','role_as_authority':'identity/role/authority distinct','unknown_target':'UNKNOWN target cannot be silently bound to task','joint_actor':'many-to-many participation; no sole actor inference','conflict_overwrite':'immutable competing assertions retained','regulator_feedback':'origin/regulator-output lineage marker exposes circularity'}}
